import React, { useEffect, useState } from "react";
import type { PushedBacklogRecord } from "../../types/chat.types";
import { getPushHistory } from "../../api/backlogApi";

interface PushHistoryPanelProps {
  sessionId?: string | null;
  refreshTrigger?: number; // increment to trigger refresh
}

const TYPE_COLORS: Record<string, string> = {
  Epic: "bg-[var(--color-purple-subtle)] text-[var(--color-purple)]",
  Story: "bg-[var(--color-success-subtle)] text-[var(--color-success)]",
  Task: "bg-[var(--color-info-subtle)] text-[var(--color-info)]",
  Subtask: "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)]",
  Bug: "bg-[var(--color-error-light)] text-[var(--color-error)]",
};

const PushHistoryPanel: React.FC<PushHistoryPanelProps> = ({
  sessionId,
  refreshTrigger,
}) => {
  const [history, setHistory] = useState<PushedBacklogRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [filter, setFilter] = useState<"all" | "session">("all");

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const data = await getPushHistory(
        filter === "session" ? sessionId || undefined : undefined
      );
      setHistory(data);
    } catch (err) {
      console.error("Failed to load push history:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen) {
      fetchHistory();
    }
  }, [isOpen, filter, refreshTrigger]);

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "Just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <>
      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`push-history-toggle hover-lift hover-glow shadow-[var(--shadow-elevation-md)] ${isOpen ? "open" : ""}`}
      >
        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
          />
        </svg>
        <span className="push-history-toggle-text">
          Push History
          {history.length > 0 && !isOpen && (
            <span className="push-history-badge shadow-sm">
              {history.length}
            </span>
          )}
        </span>
      </button>

      {/* Backdrop */}
      {isOpen && (
        <div
          className="modal-overlay"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* Slide-over Panel */}
      <div className={`slide-over-panel ${isOpen ? "open" : ""}`}>
        {/* Panel Header */}
        <div className="slide-over-header">
          <div>
            <h2 className="heading-md m-0">Push History</h2>
            <p className="text-xs text-[var(--color-text-tertiary)] font-medium mt-1 uppercase tracking-wider">
              Items pushed to Jira
            </p>
          </div>
          <button
            onClick={() => setIsOpen(false)}
            className="btn-icon text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-secondary)]"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        {/* Filter Tabs */}
        {sessionId && (
          <div className="flex px-6 pt-4 gap-2">
            <button
              onClick={() => setFilter("all")}
              className={`px-4 py-1.5 text-xs rounded-full transition-all font-semibold ${
                filter === "all"
                  ? "bg-[var(--color-accent)] text-white shadow-sm"
                  : "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)]"
              }`}
            >
              All Sessions
            </button>
            <button
              onClick={() => setFilter("session")}
              className={`px-4 py-1.5 text-xs rounded-full transition-all font-semibold ${
                filter === "session"
                  ? "bg-[var(--color-accent)] text-white shadow-sm"
                  : "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)]"
              }`}
            >
              This Session
            </button>
          </div>
        )}

        {/* History List */}
        <div className="slide-over-body custom-scrollbar">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="flex gap-1">
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "0ms" }}></div>
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "150ms" }}></div>
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "300ms" }}></div>
              </div>
            </div>
          ) : history.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state-icon border border-[var(--color-border-light)]">
                  <svg
                    className="w-8 h-8 text-[var(--color-text-tertiary)]"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={1.5}
                      d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                    />
                  </svg>
              </div>
              <p className="empty-state-title">No items pushed yet</p>
              <p className="empty-state-desc">
                Craft backlog items in the chat and push them to Jira
              </p>
            </div>
          ) : (
            history.map((item, index) => (
              <div
                key={item._id}
                className="history-card animate-fade-in-up"
                style={{ animationDelay: `${index * 0.05}s` }}
              >
                <div className="history-card-header">
                  <div className="history-card-content">
                    <div className="history-card-tags">
                      <span
                        className={`history-card-type ${
                          TYPE_COLORS[item.type] || TYPE_COLORS.Task
                        }`}
                      >
                        {item.type}
                      </span>
                      {item.jiraUrl ? (
                        <a
                          href={item.jiraUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="history-card-key"
                        >
                          {item.jiraKey}
                        </a>
                      ) : (
                        <span className="history-card-key">
                          {item.jiraKey}
                        </span>
                      )}
                    </div>
                    <p className="history-card-summary">
                      {item.summary}
                    </p>
                    {item.parentKey && (
                      <div className="history-card-parent">
                        <svg fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 11l5-5m0 0l5 5m-5-5v12" /></svg>
                        <span className="history-card-parent-text">Under {item.parentKey}</span>
                        {item.parentSummary && (
                          <span className="history-card-parent-summary">— {item.parentSummary}</span>
                        )}
                      </div>
                    )}
                  </div>
                  <div className="history-card-meta">
                    <p className="history-card-date">
                      {formatDate(item.createdAt)}
                    </p>
                    {item.storyPoints && (
                      <p className="history-card-points">
                        {item.storyPoints} SP
                      </p>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </>
  );
};

export default PushHistoryPanel;

import React, { useState, useEffect } from 'react';
import { ChevronRight, ChevronDown, CheckSquare, Square } from 'lucide-react';
import type { EpicSuggestion, StorySuggestion, TaskSuggestion } from '../../types/prd.types';
import { StoryItem } from './StoryItem';
import { usePRDSelection } from '../../hooks/usePRDSelection';

interface EpicSectionProps {
    epic: EpicSuggestion;
    epicIndex: number;
    isSelected: boolean;
    isExpanded: boolean;
    selectionInfo: ReturnType<typeof usePRDSelection>;
    onToggle: () => void;
    onToggleStory: (storyIndex: number) => void;
    onToggleTask: (storyIndex: number, taskIndex: number) => void;
    onExpand: () => void;
    onExpandStory: (id: string) => void;
    onUpdate: (updates: Partial<EpicSuggestion>) => void;
    onUpdateStory: (storyIndex: number, updates: Partial<StorySuggestion>) => void;
    onUpdateTask: (storyIndex: number, taskIndex: number, updates: Partial<TaskSuggestion>) => void;
    onOpenModal?: (type: 'Epic' | 'Story' | 'Task', epicIndex: number, storyIndex?: number, taskIndex?: number) => void;
}

export const EpicSection: React.FC<EpicSectionProps> = ({
    epic,
    epicIndex,
    isSelected,
    isExpanded,
    selectionInfo,
    onToggle,
    onToggleStory,
    onToggleTask,
    onExpand,
    onExpandStory,
    onUpdate,
    onUpdateStory,
    onUpdateTask,
    onOpenModal
}) => {
    const hasStories = epic.issues && epic.issues.length > 0;

    // Calculate intermediate state
    const selectedStoryCount = Object.values(selectionInfo.selection[epicIndex]?.stories || {}).filter(s => s.selected).length;
    const isIndeterminate = !isSelected && selectedStoryCount > 0 && selectedStoryCount < epic.issues.length;

    return (
        <div className="card mb-4 overflow-hidden">
            {/* Header / Epic Card */}
            <div className={`
                p-4 flex items-start gap-3 
                ${isExpanded ? 'bg-[var(--color-bg-secondary)] border-b border-[var(--color-border-light)]' : 'bg-[var(--color-surface)]'}
                transition-colors
            `}>
                <button
                    onClick={onExpand}
                    className="mt-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-text-primary)] transition-colors"
                >
                    {isExpanded ? <ChevronDown className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
                </button>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                        <span className="badge badge-accent uppercase tracking-wider">
                            Epic
                        </span>
                        <div className="flex-1 min-w-0">
                            <h3
                                onClick={() => onOpenModal && onOpenModal('Epic', epicIndex)}
                                className="text-base font-semibold text-[var(--color-text-primary)] truncate cursor-pointer hover:text-[var(--color-accent)] transition-colors min-h-[24px] flex items-center gap-2 group/title"
                                title="Click to view/edit details"
                            >
                                {epic.title || <span className="text-[var(--color-text-tertiary)] italic font-normal">Empty epic title</span>}
                            </h3>
                        </div>
                    </div>
                    <p className="text-sm text-[var(--color-text-secondary)] line-clamp-2 pl-1">
                        {epic.description}
                    </p>
                </div>

                <button
                    onClick={onToggle}
                    className="mt-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] transition-colors relative"
                >
                    {isSelected ? (
                        <CheckSquare className="w-5 h-5 text-[var(--color-accent)]" />
                    ) : isIndeterminate ? (
                        <div className="relative w-5 h-5">
                            <Square className="w-5 h-5" />
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-sm"></div>
                            </div>
                        </div>
                    ) : (
                        <Square className="w-5 h-5" />
                    )}
                </button>
            </div>

            {/* Stories List */}
            {isExpanded && hasStories && (
                <div className="p-2 space-y-1 bg-[var(--color-surface)]">
                    {epic.issues.map((story, storyIndex) => (
                        <StoryItem
                            key={storyIndex}
                            story={story}
                            isSelected={!!selectionInfo.selection[epicIndex]?.stories?.[storyIndex]?.selected}
                            selectionState={selectionInfo.selection[epicIndex]?.stories?.[storyIndex] || { selected: false, tasks: {} }}
                            isExpanded={!!selectionInfo.expanded[`story-${epicIndex}-${storyIndex}`]}
                            onToggle={() => onToggleStory(storyIndex)}
                            onToggleTask={(taskIndex) => onToggleTask(storyIndex, taskIndex)}
                            onExpand={() => onExpandStory(`story-${epicIndex}-${storyIndex}`)}
                            onUpdate={(updates) => onUpdateStory(storyIndex, updates)}
                            onUpdateTask={(taskIndex, updates) => onUpdateTask(storyIndex, taskIndex, updates)}
                            onOpenModal={(type, _, storyIdx, taskIdx) => onOpenModal && onOpenModal(type, epicIndex, storyIdx !== undefined ? storyIdx : storyIndex, taskIdx)}
                            isLast={storyIndex === epic.issues.length - 1}
                        />
                    ))}
                </div>
            )}

            {isExpanded && !hasStories && (
                <div className="p-8 text-center text-[var(--color-text-tertiary)] text-sm">
                    No user stories generated for this epic.
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState } from "react";
import { getPRDSessions, createPRDSession, deletePRDSession } from "../../api/scrumApi";
import type { PRDSession } from "../../types/prd.types";
import { useNavigate } from "react-router-dom";

interface PRDHistorySidebarProps {
    activeSessionId?: string;
}

const PRDHistorySidebar: React.FC<PRDHistorySidebarProps> = ({ activeSessionId }) => {
    const [sessions, setSessions] = useState<PRDSession[]>([]);
    const navigate = useNavigate();

    const fetchSessions = async () => {
        try {
            const data = await getPRDSessions();
            setSessions(data);
        } catch (error) {
            console.error("Failed to load PRD sessions", error);
        }
    };

    useEffect(() => {
        fetchSessions();
    }, [activeSessionId]); // Reload when active session changes (e.g. after create/update)

    const handleCreateNew = async () => {
        try {
            const newSession = await createPRDSession({ title: "New PRD Draft" });
            navigate(`/prd/${newSession._id}`);
        } catch (error) {
            console.error("Failed to create new PRD session", error);
        }
    };

    const handleDelete = async (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (!confirm("Are you sure you want to delete this PRD?")) return;

        try {
            await deletePRDSession(id);
            if (activeSessionId === id) {
                navigate("/prd");
            }
            fetchSessions();
        } catch (error) {
            console.error("Failed to delete PRD session", error);
        }
    };

    return (
        <div className="flex flex-col h-full bg-[var(--color-bg-primary)]">
            <div className="sidebar-header">
                <button
                    onClick={handleCreateNew}
                    className="btn btn-primary btn-full shadow-sm"
                >
                    <span>+ New PRD</span>
                </button>
            </div>

            <div className="sidebar-body stagger-children">
                {sessions.length === 0 ? (
                    <div className="empty-state p-4">
                        <p className="empty-state-desc">No previous PRDs found.</p>
                    </div>
                ) : (
                    <ul className="space-y-1 px-2">
                        {sessions.map((session, index) => (
                            <li key={session._id} style={{ '--index': index } as React.CSSProperties}>
                                <button
                                    onClick={() => navigate(`/prd/${session._id}`)}
                                    className={`sidebar-item group relative mb-1 w-full flex items-center justify-between text-left ${activeSessionId === session._id
                                            ? "sidebar-item-active"
                                            : ""
                                        }`}
                                >
                                    <span className="text-truncate flex-1">{session.title || "Untitled PRD"}</span>

                                    <span
                                        onClick={(e) => handleDelete(e, session._id)}
                                        className={`btn-icon-sm text-[var(--color-text-tertiary)] hover:bg-[var(--color-error-light)] hover:text-[var(--color-error)] opacity-0 group-hover:opacity-100 transition-opacity ml-2 shrink-0`}
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5">
                                            <path fillRule="evenodd" d="M8.75 1A2.75 2.75 0 0 0 6 3.75v.443c-.795.077-1.584.176-2.365.298a.75.75 0 1 0 .23 1.482l.149-.022.841 10.518A2.75 2.75 0 0 0 7.596 19h4.807a2.75 2.75 0 0 0 2.742-2.53l.841-10.52.149.023a.75.75 0 0 0 .23-1.482A41.03 41.03 0 0 0 14 4.193V3.75A2.75 2.75 0 0 0 11.25 1h-2.5ZM10 4c.84 0 1.673.025 2.5.075V3.75c0-.69-.56-1.25-1.25-1.25h-2.5c-.69 0-1.25.56-1.25 1.25v.325C8.327 4.025 9.16 4 10 4ZM8.58 7.72a.75.75 0 0 0-1.5.06l.3 7.5a.75.75 0 1 0 1.5-.06l-.3-7.5Zm4.34.06a.75.75 0 1 0-1.5-.06l-.3 7.5a.75.75 0 0 0 1.5.06l.3-7.5Z" clipRule="evenodd" />
                                        </svg>
                                    </span>
                                </button>
                            </li>
                        ))}
                    </ul>
                )}
            </div>
        </div>
    );
};

export default PRDHistorySidebar;

import React, { useState, useEffect } from 'react';
import { CheckSquare, Square, ChevronRight, ChevronDown } from 'lucide-react';
import type { StorySuggestion, TaskSuggestion } from '../../types/prd.types';
import { TaskItem } from './TaskItem';

interface StoryItemProps {
    story: StorySuggestion;
    isSelected: boolean;
    isExpanded: boolean;
    selectionState: { selected: boolean; tasks: Record<number, boolean> };
    onToggle: () => void;
    onToggleTask: (taskIndex: number) => void;
    onExpand: () => void;
    onUpdate: (updates: Partial<StorySuggestion>) => void;
    onUpdateTask: (taskIndex: number, updates: Partial<TaskSuggestion>) => void;
    isLast: boolean;
    onOpenModal?: (type: 'Story' | 'Task', dummy1: number, dummy2?: number, taskIndex?: number) => void;
}

export const StoryItem: React.FC<StoryItemProps> = ({
    story,
    isSelected,
    isExpanded,
    selectionState,
    onToggle,
    onToggleTask,
    onExpand,
    onUpdate,
    onUpdateTask,
    isLast,
    onOpenModal
}) => {
    const hasTasks = story.sub_issues && story.sub_issues.length > 0;

    // Determine partial selection state
    const selectedTaskCount = Object.values(selectionState.tasks || {}).filter(Boolean).length;
    const isIndeterminate = !isSelected && selectedTaskCount > 0 && selectedTaskCount < (story.sub_issues?.length || 0);

    return (
        <div className="relative">
            {/* Tree connector line */}
            <div className={`absolute left-[11px] top-0 w-[1px] bg-[var(--color-border)] ${isLast && !isExpanded ? 'h-6' : 'h-full'}`}></div>

            <div className={`
                flex items-start group relative py-2 pl-2 pr-2 rounded-lg transition-all duration-200
                ${isSelected ? 'bg-[var(--color-accent-lighter)]' : 'hover:bg-[var(--color-bg-secondary)]'}
            `}>
                {/* Horizontal connector to parent */}
                <div className="absolute left-[-13px] top-5 w-4 h-[1px] bg-[var(--color-border)]"></div>

                <div className="flex items-center mt-0.5 mr-2">
                    <button
                        onClick={onExpand}
                        disabled={!hasTasks}
                        className={`p-0.5 rounded-md transition-colors ${hasTasks ? 'hover:bg-[var(--color-bg-tertiary)] text-[var(--color-text-secondary)]' : 'text-transparent'}`}
                    >
                        {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                    </button>

                    <button
                        onClick={onToggle}
                        className="ml-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] transition-colors focus:outline-none relative"
                    >
                        {isSelected ? (
                            <CheckSquare className="w-4 h-4 text-[var(--color-accent)]" />
                        ) : isIndeterminate ? (
                            <div className="relative w-4 h-4">
                                <Square className="w-4 h-4" />
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <div className="w-2 h-2 bg-[var(--color-accent)] rounded-sm"></div>
                                </div>
                            </div>
                        ) : (
                            <Square className="w-4 h-4" />
                        )}
                    </button>
                </div>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                        <span className="badge badge-accent uppercase tracking-wide">
                            Story
                        </span>
                        <div className="flex-1 min-w-0">
                            <h4
                                onClick={() => onOpenModal && onOpenModal('Story', 0)}
                                className="text-sm font-medium text-[var(--color-text-primary)] truncate cursor-pointer hover:text-[var(--color-accent)] transition-colors min-h-[20px]"
                                title="Click to view/edit details"
                            >
                                {story.summary || <span className="text-[var(--color-text-tertiary)] italic font-normal">Empty story summary</span>}
                            </h4>
                        </div>
                        <div className="flex items-center text-xs text-[var(--color-text-tertiary)] gap-3 shrink-0">
                            {story.story_points && (
                                <span className="badge badge-neutral whitespace-nowrap">
                                    {story.story_points} pts
                                </span>
                            )}
                            <span className="whitespace-nowrap">{story.priority || 'Medium'}</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Children Tasks */}
            {isExpanded && hasTasks && (
                <div className="ml-6 pl-2 border-l border-transparent"> {/* Offset for children */}
                    {story.sub_issues.map((task, index) => {
                        const isTaskSelected = selectionState?.tasks?.[index];
                        return (
                            <TaskItem
                                key={index}
                                task={task}
                                isSelected={isTaskSelected !== undefined ? isTaskSelected : isSelected}
                                onToggle={() => onToggleTask(index)}
                                onUpdate={(updates) => onUpdateTask(index, updates)}
                                onOpenModal={() => onOpenModal && onOpenModal('Task', 0, 0, index)}
                                isLast={index === (story.sub_issues?.length || 0) - 1}
                            />
                        );
                    })}
                </div>
            )}
        </div>
    );
};

