import React, { useState, useEffect } from 'react';
import { X, Save, Play, Loader2, ListTodo, AlignLeft } from 'lucide-react';
import type { EpicSuggestion, StorySuggestion, TaskSuggestion } from '../../types/prd.types';

export type TicketType = 'Epic' | 'Story' | 'Task';

export interface TicketDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    ticketType: TicketType | null;
    ticketData: EpicSuggestion | StorySuggestion | TaskSuggestion | null;
    onSave: (updates: Record<string, unknown>) => void;
    onPush?: () => void;
    isPushing?: boolean;
}

export const TicketDetailModal: React.FC<TicketDetailModalProps> = ({
    isOpen,
    onClose,
    ticketType,
    ticketData,
    onSave,
    onPush,
    isPushing = false
}) => {
    // Local state for editing
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [acceptanceCriteria, setAcceptanceCriteria] = useState('');
    const [storyPoints, setStoryPoints] = useState<number | ''>('');
    const [priority, setPriority] = useState('Medium');

    // eslint-disable-next-line
    useEffect(() => {
        if (ticketData) {
            setTitle((ticketData as EpicSuggestion).title || (ticketData as StorySuggestion).summary || '');
            setDescription(ticketData.description || '');
            if (ticketType === 'Story') {
                const story = ticketData as StorySuggestion;
                setAcceptanceCriteria(story.acceptance_criteria?.join('\n') || '');
                setStoryPoints(story.story_points ?? '');   
                setPriority(story.priority || 'Medium');
            } else if (ticketType === 'Task') {
                const task = ticketData as TaskSuggestion;
                setPriority(task.priority || 'Medium');
            }
        }
    }, [ticketData, ticketType, isOpen]);

    if (!isOpen || !ticketData || !ticketType) return null;

    const handleSave = () => {
        const updates: Record<string, unknown> = {};
        if (ticketType === 'Epic') {
            updates.title = title;
            updates.description = description;
        } else if (ticketType === 'Story') {
            updates.summary = title;
            updates.description = description;
            updates.acceptance_criteria = acceptanceCriteria.split('\n').map(s => s.trim()).filter(s => s.length > 0);
            updates.story_points = storyPoints === '' ? undefined : Number(storyPoints);
            updates.priority = priority;
        } else if (ticketType === 'Task') {
            updates.summary = title;
            updates.description = description;
            updates.priority = priority;
        }
        onSave(updates);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-[var(--color-bg-primary)] rounded-xl shadow-xl w-full max-w-3xl flex flex-col max-h-[90vh] overflow-hidden border border-[var(--color-border)]">
                {/* Header */}
                <div className="flex items-center justify-between p-5 border-b border-[var(--color-border)] bg-[var(--color-bg-secondary)]">
                    <div className="flex items-center gap-3">
                        <span className={`px-2 py-1 text-xs font-bold uppercase tracking-wider rounded ${
                            ticketType === 'Epic' ? 'bg-purple-100 text-purple-700' :
                            ticketType === 'Story' ? 'bg-blue-100 text-blue-700' :
                            'bg-green-100 text-green-700'
                        }`}>
                            {ticketType}
                        </span>
                        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Edit Details</h2>
                    </div>
                    <button onClick={onClose} className="p-2 text-[var(--color-text-tertiary)] hover:text-[var(--color-text-primary)] transition-colors rounded-md hover:bg-[var(--color-bg-tertiary)]">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                    {/* Title / Summary */}
                    <div>
                        <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                            {ticketType === 'Epic' ? 'Title' : 'Summary'}
                        </label>
                        <input
                            type="text"
                            value={title}
                            onChange={e => setTitle(e.target.value)}
                            className="input w-full text-base font-medium"
                            placeholder={`Enter ${ticketType.toLowerCase()} ${ticketType === 'Epic' ? 'title' : 'summary'}`}
                        />
                    </div>

                    {/* Description */}
                    <div>
                        <label className="flex items-center gap-2 text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                            <AlignLeft className="w-4 h-4" /> Description
                        </label>
                        <textarea
                            value={description}
                            onChange={e => setDescription(e.target.value)}
                            className="input w-full h-32 py-3 custom-scrollbar"
                            placeholder={`Enter detailed description for this ${ticketType.toLowerCase()}...`}
                        />
                    </div>

                    {/* Story Specific Fields */}
                    {ticketType === 'Story' && (
                        <>
                            <div>
                                <label className="flex items-center gap-2 text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                    <ListTodo className="w-4 h-4" /> Acceptance Criteria
                                </label>
                                <textarea
                                    value={acceptanceCriteria}
                                    onChange={e => setAcceptanceCriteria(e.target.value)}
                                    className="input w-full h-32 py-3 custom-scrollbar font-mono text-sm"
                                    placeholder="One criterion per line..."
                                />
                            </div>
                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                        Story Points
                                    </label>
                                    <input
                                        type="number"
                                        value={storyPoints}
                                        onChange={e => setStoryPoints(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="input w-full"
                                        min="0"
                                        max="100"
                                    />
                                </div>
                                <div className="flex-1">
                                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                        Priority
                                    </label>
                                    <select
                                        value={priority}
                                        onChange={e => setPriority(e.target.value)}
                                        className="input w-full bg-white"
                                    >
                                        <option value="Highest">Highest</option>
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                        <option value="Lowest">Lowest</option>
                                    </select>
                                </div>
                            </div>
                        </>
                    )}

                    {/* Task Specific Fields */}
                    {ticketType === 'Task' && (
                        <div className="flex-1">
                            <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                Priority
                            </label>
                            <select
                                value={priority}
                                onChange={e => setPriority(e.target.value)}
                                className="input w-full bg-white"
                            >
                                <option value="Highest">Highest</option>
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                                <option value="Lowest">Lowest</option>
                            </select>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-5 border-t border-[var(--color-border)] bg-[var(--color-bg-secondary)] flex justify-between items-center">
                    <div>
                        {ticketType === 'Epic' && onPush && (
                            <button
                                onClick={onPush}
                                disabled={isPushing}
                                className="btn btn-primary bg-indigo-600 hover:bg-indigo-700 text-white flex items-center gap-2 border-transparent"
                            >
                                {isPushing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                                {isPushing ? 'Pushing to Jira...' : 'Push Epic to Jira'}
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} className="btn text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)] border-transparent">
                            Cancel
                        </button>
                        <button onClick={handleSave} className="btn btn-primary flex items-center gap-2">
                            <Save className="w-4 h-4" /> Save Changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import { useState, useCallback, useEffect, useRef } from "react";
import type { ChatMessage } from "../types/chat.types";
import { v4 as uuidv4 } from "uuid";

const CHAT_API_URL = "/api/v1/scrum/chat";

export const useChat = (
  sessionId?: string | null,
  onTitleChange?: (newTitle: string) => void,
) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Track active fetch requests
  const abortControllerRef = useRef<AbortController | null>(null);

  // Fetch messages when sessionId changes
  useEffect(() => {
    // Cancel any in-flight request for a previous session
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    if (!sessionId) {
      setMessages([]);
      return;
    }

    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    const fetchMessages = async () => {
      setLoading(true);
      setError(null);

      try {
        const token = localStorage.getItem("token");
        if (!token) return;

        const response = await fetch(`${CHAT_API_URL}/${sessionId}/messages`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
          signal: abortController.signal,
        });

        if (response.ok) {
          const data = await response.json();

          const mapped: ChatMessage[] = data.map((msg: any) => ({
            id: msg._id || uuidv4(),
            role: msg.role,
            content: msg.content,
            createdAt: msg.createdAt || new Date().toISOString(),
          }));

          if (!abortController.signal.aborted) {
            setMessages(mapped);
          }
        } else {
          if (!abortController.signal.aborted) {
            setError("Failed to load messages");
          }
        }
      } catch (err: any) {
        if (err.name !== 'AbortError' && !abortController.signal.aborted) {
          console.error("Error loading messages:", err);
          setError("Connection error while loading messages");
        }
      } finally {
        if (!abortController.signal.aborted) {
          setLoading(false);
        }
      }
    };

    fetchMessages();

    return () => {
      abortController.abort();
    };
  }, [sessionId]);

  const sendMessage = useCallback(
    async (
      text: string,
      workspace?: { boardId: number | null; sprintId: number | null },
    ) => {
      if (!text.trim() || !sessionId) return;

      // Optimistic append
      const tempId = uuidv4();
      const userMessage: ChatMessage = {
        id: tempId,
        role: "user",
        content: text,
        createdAt: new Date().toISOString(),
      };

      setMessages((prev) => [...prev, userMessage]);
      setLoading(true);
      setError(null);

      try {
        const token = localStorage.getItem("token");
        if (!token) {
          throw new Error("No authorization token found.");
        }

        const body: any = { message: text };
        if (workspace) {
          body.workspace = workspace;
        }

        const response = await fetch(`${CHAT_API_URL}/${sessionId}`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(body),
        });

        if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          throw new Error(
            errData.error || `Error ${response.status}: Failed to send message`,
          );
        }

        const data = await response.json();

        // Backend returns { userMessage, assistantMessage, sessionTitle? }
        if (data.assistantMessage) {
          const aiMessage: ChatMessage = {
            id: data.assistantMessage._id || uuidv4(),
            role: "assistant",
            content: data.assistantMessage.content,
            createdAt:
              data.assistantMessage.createdAt || new Date().toISOString(),
          };

          // Only update if we're still on the same session
          setMessages((prev) => [...prev, aiMessage]);
        }

        if (data.sessionTitle && onTitleChange) {
          onTitleChange(data.sessionTitle);
        }
      } catch (err: any) {
        console.error("Chat error:", err);
        setError(err.message || "Something went wrong talking to the AI.");

        // Remove optimistic message on error
        setMessages((prev) => prev.filter((m) => m.id !== tempId));
      } finally {
        setLoading(false);
      }
    },
    [sessionId, onTitleChange],
  );

  const resetError = useCallback(() => {
    setError(null);
  }, []);

  const clearChat = useCallback(() => {
    setMessages([]);
    setError(null);
  }, []);

  return {
    messages,
    loading,
    error,
    sendMessage,
    resetError,
    clearChat,
  };
};

import { useState, useEffect, useCallback } from 'react';
import { uploadPRD, pushSuggestionsToJira, createPRDSession, updatePRDSession, getPRDSession } from '../api/scrumApi';
import type { EpicSuggestion, PRDSuggestionsResponse, PushToJiraResponse, GeneratorOptions } from '../types/prd.types';

export type GeneratorState = 'idle' | 'uploading' | 'processing' | 'ready' | 'pushing' | 'done';

interface UsePRDGeneratorReturn {
    state: GeneratorState;
    epics: EpicSuggestion[];
    uploadProgress: number;
    error: string | null;
    sessionId: string | null;
    generatedBacklogId: string | null;
    generateSuggestions: (file: File | null, prompt: string, options: GeneratorOptions, projectKey?: string, businessDocIds?: string[]) => Promise<void>;
    pushToJira: (projectKey: string, selectedEpics: EpicSuggestion[]) => Promise<PushToJiraResponse>;
    resetgenerator: () => void;
    setEpics: React.Dispatch<React.SetStateAction<EpicSuggestion[]>>;
    loadSession: (id: string) => Promise<void>;
}

export { type GeneratorOptions };

export const usePRDGenerator = (
    initialSessionId?: string,
    boardId?: number | null,
): UsePRDGeneratorReturn => {
    const [state, setState] = useState<GeneratorState>('idle');
    const [epics, setEpics] = useState<EpicSuggestion[]>([]);
    const [uploadProgress, setUploadProgress] = useState(0);
    const [error, setError] = useState<string | null>(null);
    const [sessionId, setSessionId] = useState<string | null>(initialSessionId || null);
    const [generatedBacklogId, setGeneratedBacklogId] = useState<string | null>(null);

    // For debounced saving
    const [isDirty, setIsDirty] = useState(false);

    const [isPolling, setIsPolling] = useState(false);

    // Load session if ID provided
    const loadSession = useCallback(async (id: string) => {
        try {
            setState('processing');
            const session = await getPRDSession(id);
            setEpics(session.epics || []);
            setSessionId(session._id);
            setGeneratedBacklogId(session.generatedBacklogId || null);

            if (session.status === 'processing') {
                setState('processing');
                setIsPolling(true);
            } else if (session.status === 'failed') {
                setState('idle');
                setError(session.error || 'Generation failed.');
            } else {
                setState(session.epics?.length > 0 ? 'ready' : 'idle');
            }
        } catch (err: any) {
            console.error(err);
            setError("Failed to load session");
            setState('idle');
        }
    }, []);

    // Polling effect
    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPolling && sessionId) {
            interval = setInterval(async () => {
                try {
                    const session = await getPRDSession(sessionId);
                    if (session.status === 'ready') {
                        setEpics(session.epics || []);
                        setGeneratedBacklogId(session.generatedBacklogId || null);
                        setState('ready');
                        setIsPolling(false);
                    } else if (session.status === 'failed') {
                        setError(session.error || 'Generation failed.');
                        setState('idle');
                        setIsPolling(false);
                    }
                } catch (e) {
                    console.error("Polling error", e);
                }
            }, 3000);
        }
        return () => clearInterval(interval);
    }, [isPolling, sessionId]);

    // Auto-save effect (Debounced)
    useEffect(() => {
        if (!sessionId || !isDirty || state === 'processing' || isPolling) return;

        const timeoutId = setTimeout(async () => {
            try {
                await updatePRDSession(sessionId, { epics });
                setIsDirty(false);
            } catch (err) {
                console.error("Failed to auto-save session", err);
            }
        }, 2000); // 2 second debounce

        return () => clearTimeout(timeoutId);
    }, [epics, sessionId, isDirty, state, isPolling]);

    // Mark dirty on epics change
    useEffect(() => {
        if (sessionId && epics.length > 0 && !isPolling) {
            setIsDirty(true);
        }
    }, [epics, sessionId, isPolling]);

    const generateSuggestions = async (file: File | null, prompt: string, options: GeneratorOptions, projectKey?: string, businessDocIds?: string[]) => {
        try {
            setError(null);

            if (!file && !prompt.trim()) {
                setError("Please upload a PDF or enter instructions.");
                return;
            }

            setState('uploading');
            let currentSessionId = sessionId;

            // Create or Update Session first
            if (currentSessionId) {
                await updatePRDSession(currentSessionId, { prompt, options });
            } else {
                const newSession = await createPRDSession({
                    epics: [],
                    prompt,
                    options,
                    title: file ? `PRD: ${file.name}` : `Prompt: ${prompt.substring(0, 20)}...`
                });
                currentSessionId = newSession._id;
                setSessionId(newSession._id);
            }

            // Simulate upload progress
            const interval = setInterval(() => {
                setUploadProgress(prev => {
                    if (prev >= 90) {
                        clearInterval(interval);
                        return 90;
                    }
                    return prev + 10;
                });
            }, 200);

            // Trigger generation
            const response = await uploadPRD(file, boardId, projectKey, businessDocIds, currentSessionId, prompt);

            clearInterval(interval);
            setUploadProgress(100);

            if (response.status === 'processing') {
                setState('processing');
                setIsPolling(true);
            } else {
                // Synchronous fallback just in case
                if (response.success && (response.data?.epics || response.data)) {
                    setEpics(response.data.epics || response.data);
                    setState('ready');
                } else {
                    throw new Error(response.message || 'Failed to start generation');
                }
            }

        } catch (err: any) {
            console.error(err);
            setError(err.message || "An unexpected error occurred.");
            setState('idle');
            setIsPolling(false);
        }
    };

    const pushToJira = async (projectKey: string, selectedEpics: EpicSuggestion[]): Promise<PushToJiraResponse> => {
        setState('pushing');
        try {
            const response = await pushSuggestionsToJira({
                projectKey,
                suggestions: {
                    data: {
                        epics: selectedEpics
                    }
                }
            });

            setState('done');
            return response;
        } catch (err: any) {
            console.error(err);
            setError(err.message || "Failed to push to Jira.");
            setState('ready');
            throw err;
        }
    };

    const resetgenerator = () => {
        setState('idle');
        setEpics([]);
        setError(null);
        setUploadProgress(0);
        setSessionId(null);
        setGeneratedBacklogId(null);
    };

    return {
        state,
        epics,
        uploadProgress,
        error,
        sessionId,
        generatedBacklogId,
        generateSuggestions,
        pushToJira,
        resetgenerator,
        setEpics,
        loadSession
    };
};

import { useState, useCallback } from 'react';
import type { EpicSuggestion } from '../types/prd.types';

export interface SelectionState {
    [epicIndex: number]: {
        selected: boolean;
        stories: {
            [storyIndex: number]: {
                selected: boolean;
                tasks: {
                    [taskIndex: number]: boolean;
                };
            };
        };
    };
}

export type ExpandedState = {
    [id: string]: boolean; // format: "epic-0", "story-0-1"
};

export const usePRDSelection = (epics: EpicSuggestion[]) => {
    const [selection, setSelection] = useState<SelectionState>({});
    const [expanded, setExpanded] = useState<ExpandedState>({});

    // Initialize selection state when epics are loaded
    const initializeSelection = useCallback((newEpics: EpicSuggestion[]) => {
        const initialState: SelectionState = {};
        newEpics.forEach((epic, epicIndex) => {
            initialState[epicIndex] = {
                selected: true,
                stories: {}
            };
            epic.issues.forEach((story, storyIndex) => {
                initialState[epicIndex].stories[storyIndex] = {
                    selected: true,
                    tasks: {}
                };
                story.sub_issues.forEach((_, taskIndex) => {
                    initialState[epicIndex].stories[storyIndex].tasks[taskIndex] = true;
                });
            });
        });
        setSelection(initialState);

        // Auto-expand first epic
        if (newEpics.length > 0) {
            setExpanded({ 'epic-0': true });
        }
    }, []);

    const toggleEpic = (epicIndex: number) => {
        setSelection(prev => {
            const newState = { ...prev };
            const isSelected = !newState[epicIndex]?.selected;

            newState[epicIndex] = {
                selected: isSelected,
                stories: {}
            };

            // Cascade to children
            epics[epicIndex].issues.forEach((story, storyIndex) => {
                newState[epicIndex].stories[storyIndex] = {
                    selected: isSelected,
                    tasks: {}
                };
                story.sub_issues.forEach((_, taskIndex) => {
                    newState[epicIndex].stories[storyIndex].tasks[taskIndex] = isSelected;
                });
            });

            return newState;
        });
    };

    const toggleStory = (epicIndex: number, storyIndex: number) => {
        setSelection(prev => {
            const newState = { ...prev };
            // Deep clone the epic to avoid mutating the original object
            newState[epicIndex] = {
                ...newState[epicIndex],
                stories: { ...newState[epicIndex].stories }
            };

            const isSelected = !newState[epicIndex].stories[storyIndex]?.selected;

            // Toggle story and reset tasks
            newState[epicIndex].stories[storyIndex] = {
                selected: isSelected,
                tasks: {}
            };

            // Cascade to tasks
            epics[epicIndex].issues[storyIndex].sub_issues.forEach((_, taskIndex) => {
                newState[epicIndex].stories[storyIndex].tasks[taskIndex] = isSelected;
            });

            return newState;
        });
    };

    const toggleTask = (epicIndex: number, storyIndex: number, taskIndex: number) => {
        setSelection(prev => {
            const newState = { ...prev };

            if (!newState[epicIndex] || !newState[epicIndex].stories[storyIndex]) {
                return prev;
            }

            // Deep clone all the way down
            const oldStory = newState[epicIndex].stories[storyIndex];
            const currentTaskVal = oldStory.tasks[taskIndex];

            const newTasks = { 
                ...oldStory.tasks,
                [taskIndex]: !currentTaskVal
            };

            // Auto-check the story if ANY task is selected, uncheck if ALL are deselected
            const anyTaskSelected = Object.values(newTasks).some(Boolean);

            newState[epicIndex] = {
                ...newState[epicIndex],
                stories: {
                    ...newState[epicIndex].stories,
                    [storyIndex]: {
                        ...oldStory,
                        selected: anyTaskSelected,
                        tasks: newTasks
                    }
                }
            };

            return newState;
        });
    };

    const toggleExpand = (id: string) => {
        setExpanded(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const getSelectedCounts = () => {
        let epicCount = 0;
        let storyCount = 0;
        let taskCount = 0;

        Object.entries(selection).forEach(([_, epicState]) => {
            if (epicState.selected) epicCount++;
            // Iterate over values to avoid string key issues
            Object.values(epicState.stories).forEach((storyState: any) => {
                if (storyState.selected) storyCount++;
                Object.values(storyState.tasks).forEach((isSelected) => {
                    if (isSelected) taskCount++;
                });
            });
        });

        return { epicCount, storyCount, taskCount };
    };

    return {
        selection,
        expanded,
        initializeSelection,
        toggleEpic,
        toggleStory,
        toggleTask,
        toggleExpand,
        getSelectedCounts
    };
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getGeneratedBacklog, updateStory, approveAndPushEpic, type GeneratedBacklog } from '../api/generatedBacklogApi';
import { useWorkspaceStore } from '../store/useWorkspaceStore';
import { Check, X, Edit2, Play, AlertCircle, Loader2 } from 'lucide-react';

export const BacklogReviewPage: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const workspace = useWorkspaceStore((state) => state.workspace);
    const [backlog, setBacklog] = useState<GeneratedBacklog | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Polling setup for background pushes
    const [isPolling, setIsPolling] = useState(false);

    useEffect(() => {
        if (!id) return;
        fetchBacklog();
    }, [id]);

    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPolling && id) {
            interval = setInterval(() => {
                fetchBacklog(true);
            }, 3000);
        }
        return () => clearInterval(interval);
    }, [isPolling, id]);

    const fetchBacklog = async (silent = false) => {
        if (!silent) setLoading(true);
        try {
            const data = await getGeneratedBacklog(id!);
            setBacklog(data);
            setError(null);

            // Check if we need to poll
            const hasPushing = data.epic_statuses.some((e: any) => e.status === 'pushing');
            setIsPolling(hasPushing);

        } catch (err: any) {
            if (!silent) setError(err.message || 'Failed to load backlog');
        } finally {
            if (!silent) setLoading(false);
        }
    };

    const handlePushEpic = async (epicId: string) => {
        if (!id) return;
        try {
            await approveAndPushEpic(id, epicId);
            fetchBacklog(); // Fetch immediately to see 'pushing' status
        } catch (err: any) {
            alert(`Failed to push epic: ${err.message}`);
        }
    };

    const handlePushAll = async () => {
        if (!id || !backlog) return;

        // Find epics that are pending or failed (if tracking exists)
        if (backlog.epic_statuses && backlog.epic_statuses.length > 0) {
            const epicsToPush = backlog.epic_statuses.filter((e: any) => e.status === 'pending_review' || e.status === 'failed');
            if (epicsToPush.length === 0) return;
        }

        try {
            await approveAndPushEpic(id, null); // null epicId pushes all
            fetchBacklog(); // Fetch immediately to see 'pushing' status
        } catch (err: any) {
            alert(`Failed to push all epics: ${err.message}`);
        }
    };

    if (loading) {
        return <div className="p-8 flex items-center justify-center h-full"><Loader2 className="w-8 h-8 animate-spin text-[var(--color-accent)]" /></div>;
    }

    if (error || !backlog) {
        return <div className="p-8 text-red-500">{error || 'Backlog not found'}</div>;
    }

    const { orchestrator_contract, stories, epic_statuses, validation_report } = backlog;
    const hasPendingOrFailedEpics = !epic_statuses || epic_statuses.length === 0 || epic_statuses.some((e: any) => e.status === 'pending_review' || e.status === 'failed');
    const isPushing = epic_statuses?.some((e: any) => e.status === 'pushing');

    return (
        <div className="flex flex-col h-full bg-[var(--color-surface)] overflow-y-auto custom-scrollbar">
            {/* Header */}
            <div className="sticky top-0 z-10 bg-[var(--color-bg-primary)] border-b border-[var(--color-border)] p-6 shadow-sm">
                <div className="flex justify-between items-center max-w-5xl mx-auto">
                    <div>
                        <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">Review Generated Backlog</h1>
                        <p className="text-sm text-[var(--color-text-secondary)] mt-1">
                            {validation_report?.passed} stories passed, {validation_report?.failed_and_flagged} flagged.
                        </p>
                    </div>
                    <div className="flex gap-4 items-center">
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${backlog.status === 'fully_pushed' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                            {backlog.status.replace('_', ' ').toUpperCase()}
                        </span>

                        {(hasPendingOrFailedEpics || backlog.status === 'pending_review') && (
                            <button
                                onClick={handlePushAll}
                                disabled={isPushing}
                                className="btn btn-primary flex items-center gap-2"
                            >
                                {isPushing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                                {isPushing ? 'Pushing...' : 'Push All to Jira'}
                            </button>
                        )}

                        <button
                            onClick={() => navigate('/prd')}
                            className="btn btn-secondary"
                        >
                            Back to Generator
                        </button>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="p-6 max-w-5xl mx-auto w-full space-y-8">
                {orchestrator_contract?.epics?.map((epic: any) => {
                    const epicStories = stories.filter(s => s.epic_id === epic.id);
                    const epicStatus = epic_statuses?.find((e: any) => e.epic_id === epic.id);
                    const isPending = !epicStatus || epicStatus.status === 'pending_review';

                    return (
                        <div key={epic.id} className="bg-[var(--color-bg-primary)] rounded-xl border border-[var(--color-border)] overflow-hidden shadow-sm">
                            {/* Epic Header */}
                            <div className="p-5 border-b border-[var(--color-border)] bg-[var(--color-bg-secondary)] flex justify-between items-start">
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="px-2 py-1 text-xs font-bold bg-purple-100 text-purple-700 rounded uppercase tracking-wider">Epic</span>
                                        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">{epic.title}</h2>
                                    </div>
                                    <p className="text-sm text-[var(--color-text-secondary)] max-w-3xl">{epic.description}</p>
                                </div>
                                <div className="flex flex-col items-end gap-2">
                                    {isPending && (
                                        <button 
                                            onClick={() => handlePushEpic(epic.id)}
                                            className="btn btn-primary flex items-center gap-2"
                                        >
                                            <Play className="w-4 h-4" /> Push Epic
                                        </button>
                                    )}
                                    {epicStatus?.status === 'pushing' && (
                                        <div className="flex items-center gap-2 text-blue-600 font-medium">
                                            <Loader2 className="w-4 h-4 animate-spin" /> Pushing...
                                        </div>
                                    )}
                                    {epicStatus?.status === 'pushed' && (
                                        <div className="flex items-center gap-2 text-green-600 font-medium bg-green-50 px-3 py-1 rounded-full">
                                            <Check className="w-4 h-4" /> Pushed
                                        </div>
                                    )}
                                    {epicStatus?.status === 'failed' && (
                                        <div className="flex flex-col items-end gap-1">
                                            <div className="flex items-center gap-2 text-red-600 font-medium bg-red-50 px-3 py-1 rounded-full">
                                                <AlertCircle className="w-4 h-4" /> Push Failed
                                            </div>
                                            <button 
                                                onClick={() => handlePushEpic(epic.id)}
                                                className="text-xs text-blue-600 hover:underline"
                                            >
                                                Retry
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Epic Stories */}
                            <div className="divide-y divide-[var(--color-border-light)]">
                                {epicStories.map((story) => (
                                    <StoryReviewItem 
                                        key={story.story_id} 
                                        story={story} 
                                        backlogId={id!} 
                                        isEditable={epicStatus?.status === 'pending_review' || epicStatus?.status === 'failed'} 
                                    />
                                ))}
                                {epicStories.length === 0 && (
                                    <div className="p-6 text-center text-[var(--color-text-tertiary)] text-sm">
                                        No stories drafted for this epic.
                                    </div>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// Sub-component for individual story review
const StoryReviewItem = ({ story, backlogId, isEditable }: { story: any, backlogId: string, isEditable: boolean }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedStory, setEditedStory] = useState(story);
    const [saving, setSaving] = useState(false);

    const handleSave = async () => {
        setSaving(true);
        try {
            await updateStory(backlogId, story.story_id, editedStory);
            setIsEditing(false);
        } catch (err) {
            alert('Failed to save changes');
        } finally {
            setSaving(false);
        }
    };

    if (isEditing && isEditable) {
        return (
            <div className="p-5 bg-white space-y-4 relative">
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">User Story</label>
                    <input 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm focus:ring-2 focus:ring-[var(--color-accent)]"
                        value={editedStory.user_story}
                        onChange={e => setEditedStory({...editedStory, user_story: e.target.value})}
                    />
                </div>
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">Description</label>
                    <textarea 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm h-24 focus:ring-2 focus:ring-[var(--color-accent)] custom-scrollbar"
                        value={editedStory.description}
                        onChange={e => setEditedStory({...editedStory, description: e.target.value})}
                    />
                </div>
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">Acceptance Criteria</label>
                    <textarea 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm h-32 focus:ring-2 focus:ring-[var(--color-accent)] custom-scrollbar"
                        value={(editedStory.acceptance_criteria || []).join('\n')}
                        onChange={e => setEditedStory({...editedStory, acceptance_criteria: e.target.value.split('\n')})}
                        placeholder="One criterion per line"
                    />
                </div>
                <div className="flex justify-end gap-3 pt-2">
                    <button className="btn text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-secondary)]" onClick={() => { setIsEditing(false); setEditedStory(story); }}>Cancel</button>
                    <button className="btn btn-primary" onClick={handleSave} disabled={saving}>{saving ? 'Saving...' : 'Save Changes'}</button>
                </div>
            </div>
        );
    }

    return (
        <div className="p-5 hover:bg-[var(--color-bg-secondary)] transition-colors group relative">
            <div className="flex justify-between items-start">
                <div className="flex items-start gap-3">
                    <span className="px-2 py-0.5 mt-0.5 text-xs font-bold bg-blue-100 text-blue-700 rounded uppercase tracking-wider">Story</span>
                    <div>
                        <h4 className="text-sm font-semibold text-[var(--color-text-primary)] leading-snug">{story.user_story}</h4>
                        <div className="flex items-center gap-3 mt-2 text-xs text-[var(--color-text-tertiary)] font-medium">
                            <span className="bg-[var(--color-bg-tertiary)] px-2 py-0.5 rounded text-[var(--color-text-secondary)]">{story.story_points} pts</span>
                            <span>{story.priority}</span>
                            <span>Sprint {story.sprint}</span>
                            {story.validation_status === 'failed' && (
                                <span className="flex items-center gap-1 text-red-600 bg-red-50 px-2 py-0.5 rounded">
                                    <AlertCircle className="w-3 h-3" /> Flagged
                                </span>
                            )}
                        </div>
                    </div>
                </div>
                {isEditable && (
                    <button 
                        onClick={() => setIsEditing(true)}
                        className="p-1.5 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] hover:bg-[var(--color-accent-lighter)] rounded-md opacity-0 group-hover:opacity-100 transition-all"
                    >
                        <Edit2 className="w-4 h-4" />
                    </button>
                )}
            </div>

            {(story.description || (story.acceptance_criteria && story.acceptance_criteria.length > 0)) && (
                <div className="mt-4 ml-12 text-sm text-[var(--color-text-secondary)] bg-white border border-[var(--color-border-light)] p-3 rounded-lg shadow-sm">
                    {story.description && (
                        <div className="mb-3">
                            <strong className="text-xs uppercase tracking-wider text-[var(--color-text-tertiary)] mb-1 block">Description</strong>
                            <p className="whitespace-pre-wrap">{story.description}</p>
                        </div>
                    )}
                    {story.acceptance_criteria && story.acceptance_criteria.length > 0 && (
                        <div>
                            <strong className="text-xs uppercase tracking-wider text-[var(--color-text-tertiary)] mb-1 block">Acceptance Criteria</strong>
                            <ul className="list-disc pl-5 space-y-1">
                                {story.acceptance_criteria.map((ac: string, i: number) => (
                                    <li key={i}>{ac}</li>
                                ))}
                            </ul>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

