        style={{ marginTop: "20px", padding: "10px", marginLeft: "10px" }}>
        Go to AI Chat
      </button>

      {activeSprintIssues.length > 0 && (
        <div style={{ marginTop: "20px" }}>
          <h2>Active Sprint Issues</h2>
          <ul>
            {activeSprintIssues.map((issue: any) => (
              <li key={issue.id}>
                {issue.key}: {issue.fields.summary}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

